using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Passalong.Core.Entities;using Passalong.Infrastructure.Persistence;
namespace Passalong.Api.Controllers;
public record CreateReviewRequest(Guid TransferId,int Rating,string? Comment);
[Authorize,ApiController,Route("api/reviews")]public class ReviewsController(PassalongDbContext db):ControllerBase{Guid Me=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpPost]public async Task<IActionResult>Create(CreateReviewRequest x){if(x.Rating is <1 or >5)return BadRequest("Rating must be from 1 to 5.");var t=await db.Transfers.FindAsync(x.TransferId);if(t is null||(t.PreviousOwnerId!=Me&&t.NewOwnerId!=Me))return Forbid();var other=t.PreviousOwnerId==Me?t.NewOwnerId:t.PreviousOwnerId;if(await db.Reviews.AnyAsync(r=>r.TransferId==x.TransferId&&r.ReviewerId==Me))return Conflict("You already reviewed this transfer.");db.Reviews.Add(new Review{TransferId=x.TransferId,ReviewerId=Me,ReviewedUserId=other,Rating=x.Rating,Comment=x.Comment});var u=await db.Users.FindAsync(other);if(u is not null)u.ReputationScore+=x.Rating;await db.SaveChangesAsync();return Ok();}}
